/**
 * Simple script to generate placeholder overlay images for demo purposes
 * Run with: node scripts/generate-placeholder-overlays.js
 * 
 * This creates placeholder PNG images in public/mocks/overlays/
 * In production, these would be generated by your tile service
 */

const fs = require('fs')
const path = require('path')

// Create directories if they don't exist
const regions = ['region-1', 'region-2']
const dates = [
  '2024-01-01', '2024-01-15', '2024-01-30'
]
const layers = ['changeMask', 'confidence']

regions.forEach(regionId => {
  dates.forEach(date => {
    layers.forEach(layer => {
      const dir = path.join(__dirname, '..', 'public', 'mocks', 'overlays', regionId)
      if (!fs.existsSync(dir)) {
        fs.mkdirSync(dir, { recursive: true })
      }
      
      const filename = `${date}-${layer}.png`
      const filepath = path.join(dir, filename)
      
      // Create a simple placeholder file (1x1 transparent PNG)
      // In a real scenario, you'd generate actual overlay images here
      // For now, we'll just create an empty file as a placeholder
      // The MapViewer will handle missing images gracefully
      
      if (!fs.existsSync(filepath)) {
        // Create a minimal PNG header (1x1 transparent)
        // This is a minimal valid PNG file
        const minimalPNG = Buffer.from([
          0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A, // PNG signature
          0x00, 0x00, 0x00, 0x0D, 0x49, 0x48, 0x44, 0x52, // IHDR chunk
          0x00, 0x00, 0x00, 0x01, 0x00, 0x00, 0x00, 0x01, // 1x1 image
          0x08, 0x06, 0x00, 0x00, 0x00, 0x1F, 0x15, 0xC4, 0x89,
          0x00, 0x00, 0x00, 0x0A, 0x49, 0x44, 0x41, 0x54, // IDAT chunk
          0x78, 0x9C, 0x63, 0x00, 0x01, 0x00, 0x00, 0x05, 0x00, 0x01,
          0x0D, 0x0A, 0x2D, 0xB4, 0x00, 0x00, 0x00, 0x00, 0x49, 0x45, 0x4E, 0x44, // IEND
          0xAE, 0x42, 0x60, 0x82
        ])
        
        fs.writeFileSync(filepath, minimalPNG)
        console.log(`Created placeholder: ${filepath}`)
      }
    })
  })
})

console.log('\n✅ Placeholder overlay images generated!')
console.log('Note: These are minimal 1x1 PNG files. Replace with actual overlay images in production.')

